  userName,
  userEmail,
  userAvatarUrl,
  role,
  plan = 'solo',
  allMemberships,
  currentStudioId,
  currentLocationId,
  allLocations,
  permissionKeys,
  dynamicBadges,
  children,
}: AppHeaderProps) {
  const pathname = usePathname()
  const router = useRouter()
  const queryClient = useQueryClient()

  useFocusOnRouteChange()
  const { resolvedTheme, setTheme } = useTheme()
  const supabase = createClient()

  const [paletteOpen, setPaletteOpen] = useState(false)
  const [addClientOpen, setAddClientOpen] = useState(false)
  const [newAppointmentOpen, setNewAppointmentOpen] = useState(false)
  const [mobileNavOpen, setMobileNavOpen] = useState(false)

  const lastKeyRef = useRef<string>('')
  const lastKeyTimeRef = useRef<number>(0)

  const pageLabel = getPageLabel(pathname)

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setPaletteOpen(true)
        return
      }
      if ((e.metaKey || e.ctrlKey) && e.shiftKey && e.key === 'l') {
        e.preventDefault()
        setTheme(resolvedTheme === 'dark' ? 'light' : 'dark')
        return
      }
      if (e.metaKey || e.ctrlKey || e.altKey) return
      const target = e.target as HTMLElement
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return
      if (target.isContentEditable) return

      const key = e.key.toLowerCase()
      const now = Date.now()

      if (
        lastKeyRef.current === 'g' &&
        now - lastKeyTimeRef.current < G_CHORD_TIMEOUT_MS &&
        G_CHORD_MAP[key]
      ) {
        e.preventDefault()
        router.push(G_CHORD_MAP[key])
        lastKeyRef.current = ''
        return
      }

      if (key === 'n') {
        router.push('/appointments/new')
      }

      lastKeyRef.current = key
      lastKeyTimeRef.current = now
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [router, resolvedTheme, setTheme])

  async function handleSignOut() {
    await supabase.auth.signOut()
    router.push('/login')
    router.refresh()
  }

  return (
    <SidebarInset className="flex flex-col">
      <header className="sticky top-0 z-40 flex h-14 shrink-0 items-center gap-3 border-b border-border/60 bg-background/80 px-4 backdrop-blur-md supports-[backdrop-filter]:bg-background/70">
        <div className="flex min-w-0 flex-1 items-center gap-2">
          <MobileNav
            userName={userName}
            userEmail={userEmail ?? ''}
            userAvatarUrl={userAvatarUrl}
            studioName={studioName}
            {...(studioSlug !== undefined ? { studioSlug } : {})}
            role={role}
            plan={plan}
            locationCount={allLocations.length}
            permissionKeys={permissionKeys}
            {...(dynamicBadges !== undefined ? { dynamicBadges } : {})}
            onSignOut={handleSignOut}
            open={mobileNavOpen}
            onOpenChange={setMobileNavOpen}
            allMemberships={allMemberships}
            currentStudioId={currentStudioId}
            currentLocationId={currentLocationId}
            allLocations={allLocations}
          />
          <SidebarTrigger className="hidden h-8 w-8 shrink-0 text-muted-foreground/70 hover:text-foreground md:flex" />
          <Separator orientation="vertical" className="h-4 bg-border/50" />

          <Breadcrumb className="min-w-0">
            <BreadcrumbList className="gap-1.5 text-[13px]">
              <BreadcrumbItem className="hidden md:flex">
                {allMemberships.length >= 2 ? (
                  <StudioSwitcher
                    currentStudioId={currentStudioId}
                    allMemberships={allMemberships}
                  />
                ) : (
                  <BreadcrumbLink
                    href="/today"
                    className="truncate text-muted-foreground/80 transition-colors hover:text-foreground"
                  >
                    {studioName}
                  </BreadcrumbLink>
                )}
              </BreadcrumbItem>

              {allLocations.length >= 2 && (
                <>
                  <BreadcrumbSeparator className="hidden md:flex">
                    <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40" aria-hidden="true" />
                  </BreadcrumbSeparator>
                  <BreadcrumbItem className="hidden md:flex">
                    <LocationSwitcher
                      currentLocationId={currentLocationId}
                      allLocations={allLocations}
                      role={role}
                    />
                  </BreadcrumbItem>
                </>
              )}

              {pathname !== '/today' && (
                <>
                  <BreadcrumbSeparator className="hidden md:flex">
                    <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40" aria-hidden="true" />
                  </BreadcrumbSeparator>
                  <BreadcrumbItem className="hidden md:flex">
                    <BreadcrumbPage className="truncate font-semibold tracking-tight text-foreground">
                      {pageLabel}
                    </BreadcrumbPage>
                  </BreadcrumbItem>
                </>
              )}

              <BreadcrumbItem className="flex md:hidden">
                <BreadcrumbPage className="truncate font-semibold text-foreground">
                  {pathname === '/today' ? studioName : pageLabel}
                </BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>

          <div aria-live="polite" aria-atomic="true" className="sr-only" id="studio-switch-announcement" />
        </div>

        <div className="flex shrink-0 items-center gap-1.5">
          <Button
            variant="ghost"
